#!/usr/bin/env bash
set -euo pipefail
umask 077
VERSION="1.0.0-rc6"
EXPECTED_SHA256="046bfdf8f1004611021a4f2aaa42e899b233076a8cc9cf32f8c0ca5eef98ab4e"
usage() {
  cat <<'HADS_NEXT_USAGE'
HADS Next 1.0.0-rc6 — samostatná vývojová aplikace, nikoli produkční RC.
Použití:
  bash HADS_Next_install_1.0.0-rc6.sh --verify
  bash HADS_Next_install_1.0.0-rc6.sh --extract-only /absolutni/novy-adresar
  bash HADS_Next_install_1.0.0-rc6.sh --install-dev
  bash HADS_Next_install_1.0.0-rc6.sh --upgrade-rc5
Nová instalace přidá local_hads_next_practical. Výslovný --upgrade-rc5 aktualizuje jen ověřený Next RC5 přes nativní Supervisor update; zachová /data a vyžádá nativní částečnou zálohu. Starý Hermes 2.0.0-rc3 se nemění.
Původní Hermes je součástí balíčku. AI i vlastní testovací opravný katalog vyžadují výslovný souhlas. Obecné produkční zápisy jsou zakázané. Živá HAOS přejímka čeká.
HADS_NEXT_USAGE
}
MODE="${1:-}"
case "$MODE" in
  --help) [ "$#" = 1 ] || exit 2; usage; exit 0 ;;
  --verify|--install-dev|--upgrade-rc5) [ "$#" = 1 ] || { usage; exit 2; } ;;
  --extract-only) [ "$#" = 2 ] || { usage; exit 2; } ;;
  *) usage; exit 2 ;;
esac
command -v python3 >/dev/null || { echo 'Chybí python3 v terminálové aplikaci. Podrobnosti jsou v návodu DOCS.md.' >&2; exit 1; }
command -v base64 >/dev/null || { echo 'Chybí base64.' >&2; exit 1; }
STAGING="$(mktemp -d /tmp/hads-next-install.XXXXXX)"
cleanup() {
  case "$STAGING" in /tmp/hads-next-install.*) rm -rf -- "$STAGING" ;; esac
}
trap cleanup EXIT
base64 -d > "$STAGING/payload.tar.gz" <<'HADS_NEXT_PAYLOAD'
